CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;

CREATE TABLE t_e_marque_pro (
    "idMarque" integer GENERATED BY DEFAULT AS IDENTITY,
    "nomMarque" character varying(50) NOT NULL,
    CONSTRAINT t_e_marque_pro_pkey PRIMARY KEY ("idMarque")
);

CREATE TABLE t_e_typeproduit_pro (
    "idTypeProduit" integer GENERATED BY DEFAULT AS IDENTITY,
    "nomTypeProduit" character varying(50) NOT NULL,
    CONSTRAINT t_e_typeproduit_pro_pkey PRIMARY KEY ("idTypeProduit")
);

CREATE TABLE t_e_produit_pro (
    "idProduit" integer GENERATED BY DEFAULT AS IDENTITY,
    "nomProduit" character varying(50) NOT NULL,
    description character varying(50) NOT NULL,
    "nomPhoto" character varying(50) NOT NULL,
    "uriPhoto" character varying(50) NOT NULL,
    "idMarque" integer NOT NULL,
    "idTypeProduit" integer NOT NULL,
    "StockReel" integer,
    "StockMin" integer,
    "StockMax" integer,
    "MarqueIdMarque" integer,
    "TypeProduitIdTypeProduit" integer,
    "idMarque1" integer NOT NULL,
    "idTypeProduit1" integer NOT NULL,
    CONSTRAINT t_e_produit_pro_pkey PRIMARY KEY ("idProduit"),
    CONSTRAINT "FK_t_e_produit_pro_t_e_marque_pro_MarqueIdMarque" FOREIGN KEY ("MarqueIdMarque") REFERENCES t_e_marque_pro ("idMarque"),
    CONSTRAINT "FK_t_e_produit_pro_t_e_typeproduit_pro_TypeProduitIdTypeProduit" FOREIGN KEY ("TypeProduitIdTypeProduit") REFERENCES t_e_typeproduit_pro ("idTypeProduit"),
    CONSTRAINT fk_marque FOREIGN KEY ("idMarque") REFERENCES t_e_marque_pro ("idMarque"),
    CONSTRAINT fk_typeproduit FOREIGN KEY ("idTypeProduit") REFERENCES t_e_typeproduit_pro ("idTypeProduit")
);

CREATE INDEX "IX_t_e_produit_pro_idMarque" ON t_e_produit_pro ("idMarque");

CREATE INDEX "IX_t_e_produit_pro_idTypeProduit" ON t_e_produit_pro ("idTypeProduit");

CREATE INDEX "IX_t_e_produit_pro_MarqueIdMarque" ON t_e_produit_pro ("MarqueIdMarque");

CREATE INDEX "IX_t_e_produit_pro_TypeProduitIdTypeProduit" ON t_e_produit_pro ("TypeProduitIdTypeProduit");

